const ACTIVE = ['queued', 'ready', 'running', 'turn', 'blocked', 'split'];
const DONE = ['landed', 'closed', 'failed', 'stopped'];

const remembered = { mine: false, repo: '', text: '' };

export function Jobs() {
  const { state, refresh } = useApp();
  const [filter, setFilter] = useState(remembered);
  const set = (change: Partial<typeof remembered>) => setFilter(f => ({ ...Object.assign(remembered, { ...f, ...change }) }));
  const repos = [...new Set<string>(state.jobs.map((j: Json) => j.repo))].sort();
  const words = filter.text.trim().toLowerCase();
  const jobs: Json[] = state.jobs.filter((j: Json) => (!filter.mine || j.requester === state.me.login)
    && (!filter.repo || j.repo === filter.repo)
    && (!words || `${j.title} @${j.requester}`.toLowerCase().includes(words)));
  const waiting = jobs.filter(j => j.state === 'needs_you');
  const active = jobs.filter(j => ACTIVE.includes(j.state));
  const previews = jobs.filter(j => j.state === 'waiting');
  const done = jobs.filter(j => DONE.includes(j.state));
  const canAsk = 'Notification' in window && Notification.permission === 'default';
  return (
    <>
      <PageHeader title="Jobs">
        <div className="mt-2.5 flex flex-wrap gap-2">
          {canAsk && (
            <button type="button" onClick={() => Notification.requestPermission().then(() => refresh())}>
              <Icon icon={Bell} />Tell me when a job needs me
            </button>
          )}
          {state.me.role !== 'viewer' && <a className="button primary" href={href('/new')}><Icon icon={Plus} />New request</a>}
        </div>
      </PageHeader>
      <SetupBanner />
      <div className="filters" role="search">
        <label className="inline">
          <input type="checkbox" checked={filter.mine} onChange={e => set({ mine: e.target.checked })} /> Only mine
