        <Field label="Repository">{p => (
          <select {...p} value={filter.repo} onChange={e => set({ repo: e.target.value })}>
            <option value="">Every repository</option>
            {repos.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        )}</Field>
        <Field label="Search">{p => (
          <span className="relative block [&_.icon]:pointer-events-none [&_.icon]:absolute [&_.icon]:top-1/2 [&_.icon]:left-3 [&_.icon]:-translate-y-1/2 [&_.icon]:text-muted [&_input]:pl-9">
            <Icon icon={Search} size={16} />
            <input {...p} type="search" value={filter.text} placeholder="Title or @person"
              onChange={e => set({ text: e.target.value })} />
          </span>
        )}</Field>
      </div>
      {state.jobs_total > state.jobs.length && (
        <p className="muted">Showing the newest {state.jobs.length} of {state.jobs_total} jobs.</p>
      )}
      {waiting.length > 0 && (
        <Card need title={`Waiting for you (${waiting.length})`} id="waiting-h">
          <JobList jobs={waiting} label="Waiting for you" />
        </Card>
      )}
      <section aria-labelledby="active-h" className="my-6">
        <h2 id="active-h">In progress ({active.length})</h2>
        <JobList jobs={active} label="In progress" />
      </section>
      <section aria-labelledby="preview-h" className="my-6">
        <h2 id="preview-h">Previews live ({previews.length})</h2>
        <p className="muted">Each is a change running in its own temporary environment while its pull request is open. Merging tears it down.</p>
        <JobList jobs={previews} label="Previews live" />
      </section>
      <Fold className="my-6" summary={`Finished (${done.length})`}>
        <JobList jobs={done} label="Finished" />
      </Fold>
    </>
  );
}

