      {job.error && <Card need title="This job failed"><Output text={job.error} label="The error" /></Card>}
      {job.state === 'turn' && <Watch key={job.turn?.session_id} job={job} />}
      {job.stage === 'preview' && job.state === 'waiting' && job.merge_oversight?.level === 'hold' && job.signoff?.sha === job.pushed_sha &&
        <Card title="The merge" id="merge-oversight-h"><OversightNote held={job.merge_oversight} what="merges or stops it" /></Card>}
      {['provision', 'prepare'].includes(job.stage) && ['queued', 'ready', 'running'].includes(job.state) &&
        <Setup job={job} prepare={data.prepare} log={data.log || []} />}

      <div className="grid gap-x-5.5 min-[1240px]:grid-cols-[minmax(0,1fr)_320px] min-[1240px]:items-start">
        {/* The essentials, beside the story on a wide screen and before it on a phone. */}
        <aside aria-label="This job at a glance" className="min-[1240px]:sticky min-[1240px]:top-5 min-[1240px]:col-start-2 min-[1240px]:row-start-1 [&>.actions]:mb-3.5 [&>.actions]:rounded-card [&>.actions]:border [&>.actions]:border-line [&>.actions]:bg-panel [&>.actions]:p-3.5 [&>.actions]:shadow-card min-[1240px]:[&>.actions]:flex-col min-[1240px]:[&>.actions]:items-stretch">
          <Links job={job} />
          <Deploy job={job} />
          <Escapes job={job} canAct={canAct} />
          <Parts job={job} />
          {canAct && <Controls job={job} />}
        </aside>

        <div className="min-w-0 min-[1240px]:col-start-1 min-[1240px]:row-start-1">
          <p className="eyebrow">What was asked</p>
          <Asked job={job} />
          <RequestCard job={job} />
          {job.plan && job.stage !== 'approve' && <Fold className="card" summary={<strong>The plan</strong>}><Markdown text={job.plan} /></Fold>}
          {/* Written and failing first after the plan was approved: what the build is held to. */}
          {job.checks_summary && <Fold className="card" summary={<strong>The checks the build is held to</strong>}><Markdown text={job.checks_summary} /></Fold>}
          {(job.tests_written || []).length > 0 && (
            <Fold className="card" summary={<><strong>Tests written</strong> <span className="muted">({job.tests_written.length} file{job.tests_written.length === 1 ? '' : 's'}, by layer)</span></>}>
              <TestsByLayer tests={job.tests_written} />
            </Fold>
          )}

          {job.kind === 'backtest' && <><p className="eyebrow">What the gates found</p><BacktestDetails job={job} /></>}
          {job.kind !== 'backtest' && (job.comprehension || job.checks || job.quality || job.review || job.proof || job.sprite) && <p className="eyebrow">What was built, and how it was checked</p>}
          <Briefing job={job} />
          <Guardrails job={job} criteria={data.criteria || []} uat={data.uat || []} />
          <Change job={job} />

          <p className="eyebrow">Constraints and learning</p>
          <ConstraintsPanel job={job} events={data.constraint_events || []} />
          <LearnedPanel job={job} proposals={data.proposals || []} />
          {canAct && job.state !== 'queued' && <SuggestForm job={job} evidence={data.evidence || []} />}

          <p className="eyebrow">Sessions</p>
          <TurnsPanel job={job} />
          <Timeline job={job} />
          <WhatHappened entries={data.log || []} decisions={data.decisions || []} />
          {state.me.role === 'admin' && (
            <p><a href={href('/audit')} onClick={() => Object.assign(auditFilter, { job: job.id, actor: '', action: '' })}>
              <Icon icon={ScrollText} />What people decided on this job, in the audit log</a></p>
          )}
        </div>
      </div>
    </>
  );
}
